head.script:
scwin.getType = function(info) {
	var rowIndex = info.rowIndex;
	var colIndex = info.colIndex;
	var returnInfo;
	var inputType = inputTypeList.getCellData(rowIndex, colIndex);
	switch (inputType) {
		case "radio":
			returnInfo = {
				id: "dynamic_radio_" + rowIndex + "_" + colIndex,
				inputType: "radio",
				options: {
					groupName: "radio_" + rowIndex
				}
			}
			break;
		case "checkbox":
			returnInfo = {
				id: "dynamic_checkbox_" + rowIndex + "_" + colIndex,
				inputType: "checkbox",
				options: {}
			}
			break;
		case "button":
			returnInfo = {
				id: "dynamic_button_" + rowIndex + "_" + colIndex,
				inputType: "button",
				options: {}
			}
			break;
		case "calendar":
			returnInfo = {
				id: "dynamic_calendar_" + rowIndex + "_" + colIndex,
				inputType: "calendar",
				options: {
					viewType: "icon"
				}
			}
			break;
		case "image":
			returnInfo = {
				id: "dynamic_image_" + rowIndex + "_" + colIndex,
				inputType: "image",
				options: {
					imageSrc: "s2.gif"
				}
			}
			break;
		case "link":
			returnInfo = {
				id: "dynamic_link_" + rowIndex + "_" + colIndex,
				inputType: "link",
				options: {}
			}
			break;
		case "select":
			returnInfo = {
				id: "dynamic_select_" + rowIndex + "_" + colIndex,
				inputType: "select",
				options: {
					viewType: "icon"
				},
				itemSet: {
					nodeset: "data:comboData",
					label: "DNAME",
					value: "DEPTNO"
				}
			}
			break;
		case "autoComplete":
			returnInfo = {
				id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
				inputType: "autoComplete",
				options: {
					viewType: "icon"
				},
				itemSet: {
					nodeset: "data:comboData",
					label: "DNAME",
					value: "DEPTNO"
				}
			}
			break;
		case "checkcombobox":
			returnInfo = {
				id: "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
				inputType: "checkcombobox",
				options: {
					viewType: "icon"
				},
				itemSet: {
					nodeset: "data:comboData",
					label: "DNAME",
					value: "DEPTNO"
				}
			}
			break;
		case "textarea":
			returnInfo = {
				id: "dynamic_textarea_" + rowIndex + "_" + colIndex,
				inputType: "textarea",
				options: {}
			}
			break;
		case "text":
			returnInfo = {
				id: "dynamic_text_" + rowIndex + "_" + colIndex,
				inputType: "text",
				options: {
					"class": "ta"
				}
			}
			break;
		case "textImage":
			returnInfo = {
				id: "dynamic_textImage_" + rowIndex + "_" + colIndex,
				inputType: "textImage",
				options: {
					viewType: "icon",
					imageSrc: "s.gif",
					textAlign: "center"
				}
			}
			break;
	}
	return returnInfo;
};
scwin.onpageload = function() {
	var dataArr = ["radio",
		"checkbox",
		"button",
		"calendar",
		"image",
		"link",
		"select",
		"autoComplete",
		"checkcombobox",
		"textarea",
		"text",
		"textImage"
	];
	var tempData = [];
	var tempData2 = [];
	for (var i = 0; i < 200; i++) {
		var data = dataArr[i % dataArr.length];
		var data2 = data;
		if (data === "image") {
			data2 = "s2.gif";
		}
		tempData.push(data);
		tempData2.push(data2);
	}
	inputTypeList.setData(tempData.slice(0));
	var jsonData = [];
	for (var r = 0; r < 12; r++) {
		jsonData.push({
			"col1": tempData2[r * 5],
			"col2": tempData2[r * 5 + 1],
			"col3": tempData2[r * 5 + 2],
			"col4": tempData2[r * 5 + 3],
			"col5": tempData2[r * 5 + 4]
		});
	}
	dataList1.setJSON(jsonData);
};
